import {jointEntry,jointEntryHash,jointExpectedRegistry,jointSourceText,jointSourceHash} from '../verify-reference.mjs';
const JOINT_SOURCE_URL=new URL("../../tenth-low-coupling/verify-reference.mjs",import.meta.url);
// Expected-side forward composition. No actual entry is rewritten into historical data.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
export const tenthSha=x=>createHash('sha256').update(x).digest('hex');
const read=p=>JSON.parse(fs.readFileSync(new URL(p,JOINT_SOURCE_URL),'utf8'));
export const tenthProof=read('./transition-proof.json');
const p=tenthProof,R=p.records,get=(o,path)=>path.reduce((v,k)=>v[k],o),set=(o,path,v)=>path.slice(0,-1).reduce((v,k)=>v[k],o)[path.at(-1)]=v;
export const tenthCanon=x=>JSON.stringify((function sort(v){if(Array.isArray(v))return v.map(sort);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])]));return v;})(x));
assert.equal(R.length,14);assert.equal(new Set(R.map(r=>JSON.stringify([r.entryId,r.path]))).size,14);assert.equal(Object.keys(p.originalEntries).length,9);
for(const r of R){for(const side of ['before','after'])assert.equal(tenthSha(r[side]),r[side+'Sha256']);assert.equal(get(p.originalEntries[r.entryId],r.path),r.before);assert.equal(get(p.finalEntries[r.entryId],r.path),r.after);}
export function tenthEntry(old){if(!Object.hasOwn(p.originalEntries,old.id))return jointEntry(structuredClone(old));assert.deepEqual(old,p.originalEntries[old.id],'entire original expected entry before tenth forward composition '+old.id);const next=structuredClone(old);for(const r of R.filter(r=>r.entryId===old.id)){assert.equal(get(next,r.path),r.before);set(next,r.path,r.after);}assert.deepEqual(next,p.finalEntries[old.id]);return jointEntry(next);}
export function tenthEntryHash(id,old){if(!Object.hasOwn(p.originalEntries,id))return jointEntryHash(id,old);assert.equal(old,p.originalCanonicalHashes[id],'exact old expected canonical hash '+id);return jointEntryHash(id,p.finalCanonicalHashes[id]);}
export function tenthEntryOrder(old){assert.deepEqual(old,p.originalEntryOrder,'complete exact original chapter traversal required');return structuredClone(p.finalEntryOrder);}
export function assertTenthEntries(entries){assert.equal(entries.length,803);const E=new Map(entries.map(e=>[e.id,e]));assert.equal(E.size,803);assert.deepEqual(entries.map(e=>e.id),p.finalEntryOrder,'exact complete current DSL-aware chapter traversal');for(const e of entries){assert.equal(tenthSha(tenthCanon(e)),jointEntryHash(e.id,p.finalCanonicalHashes[e.id]),'entire current canonical entry '+e.id);if(Object.hasOwn(p.finalEntries,e.id))assert.deepEqual(e,jointEntry(p.finalEntries[e.id]),'entire current tenth entry '+e.id);}return {leaves:14,entries:9,corpusEntries:803};}
let registry527,registry541;
export function tenthRegistryExpected(){if(registry541)return structuredClone(registry541);const raw=fs.readFileSync(new URL('./original527-registry.json',JOINT_SOURCE_URL));assert.equal(tenthSha(raw),p.registryBeforeSha256);registry527=JSON.parse(raw);assert.equal(registry527.records.length,527);const expected=structuredClone(registry527),seen=new Set(expected.records.map(r=>JSON.stringify([r.entryId,r.path])));for(const r of R){const k=JSON.stringify([r.entryId,r.path]);assert.ok(!seen.has(k),'tenth must contain14 wholly new exact registry keys');seen.add(k);expected.records.push(Object.fromEntries(['entryId','path','before','after','beforeSha256','afterSha256','reason'].map(k=>[k,r[k]])));}assert.equal(expected.records.length,541);registry541=jointExpectedRegistry(expected);return structuredClone(registry541);}
export function tenthRegistryReference527(current){assert.deepEqual(current,tenthRegistryExpected(),'complete541 current registry required before explicitly labeled historical527 reference');return structuredClone(registry527);}
let sources;
export function tenthSourceProof(){return sources??=read('./source-transitions.json');}
export function tenthSourceText(target,old){const r=tenthSourceProof().replacements.find(r=>r.target===target);if(!r)return jointSourceText(target,old);assert.equal(old,r.before,'exact ninth/current527 source expected before tenth '+target);return jointSourceText(target,r.after);}
export function tenthSourceHash(target,old){const r=tenthSourceProof().replacements.find(r=>r.target===target);if(!r)return jointSourceHash(target,old);assert.equal(old,r.beforeSha256,'exact ninth/current527 source hash expected before tenth '+target);return jointSourceHash(target,r.afterSha256);}
export function verifyTenthSourceRow(r){assert.equal(tenthSha(r.before),r.beforeSha256);assert.equal(tenthSha(r.after),r.afterSha256);const b=Buffer.from(r.before),parts=[];let pos=0;for(const e of r.edits){assert.ok(Number.isInteger(e.beforeStartByte)&&e.beforeStartByte>=pos);assert.ok(Number.isInteger(e.beforeEndByte)&&e.beforeEndByte>=e.beforeStartByte);assert.equal(b.subarray(e.beforeStartByte,e.beforeEndByte).toString(),e.before);parts.push(b.subarray(pos,e.beforeStartByte),Buffer.from(e.after));pos=e.beforeEndByte;}parts.push(b.subarray(pos));assert.equal(Buffer.concat(parts).toString(),r.after,'exact whole source reconstructed from byte edits');}
export function assertTenthSources(siteRoot=new URL('../../../',JOINT_SOURCE_URL)){const s=tenthSourceProof(),seen=new Set();assert.equal(s.clones.length,4);assert.equal(s.replacements.length,9);for(const r of [...s.clones,...s.replacements]){assert.ok(!seen.has(r.target));seen.add(r.target);verifyTenthSourceRow(r);if(r.originalTarget!==r.target){assert.ok(r.originalTarget.startsWith('tests/fixtures/ninth-small-repairs/'));assert.equal(fs.readFileSync(new URL(r.originalTarget,siteRoot),'utf8'),r.before,'immutable original ninth executable');}assert.equal(fs.readFileSync(new URL(r.target,siteRoot),'utf8'),jointSourceText(r.target,r.after),'exact installed tenth source '+r.target);}return {clones:4,replacements:9,originalFixtureWrites:0};}
export function assertTenthCatalog(actual){const c=read('./catalog-proof.json');assert.deepEqual(actual,c.after,'complete catalog, including DSL chunk and unchanged metadata');assert.deepEqual(actual.entries.map(e=>e.id),p.catalogEntryOrder);return c;}
